// Reads prototypes/*/metadata.json and sites/*.json and writes lib/generated/{manifest.json,registry.ts}.
// Runs before dev, build, lint and typecheck. The generated files are not committed.
import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
import { join } from "node:path";

const root = new URL("..", import.meta.url).pathname;
const SLUG = /^[a-z0-9][a-z0-9-]*$/;
const fail = (msg) => {
  console.error(`manifest: ${msg}`);
  process.exit(1);
};
const readJson = (path) => {
  try {
    return JSON.parse(readFileSync(path, "utf8"));
  } catch (e) {
    fail(`${path} is not valid JSON: ${e.message}`);
  }
};
const has = (rel) => existsSync(join(root, "public", rel));
const common = (slug, m, where) => {
  for (const key of ["title", "description", "createdAt", "updatedAt"]) {
    if (typeof m[key] !== "string" || !m[key]) fail(`${where} needs a "${key}" string`);
  }
  return {
    slug,
    title: m.title,
    description: m.description,
    tags: Array.isArray(m.tags) ? m.tags : [],
    createdAt: m.createdAt,
    updatedAt: m.updatedAt,
    hidden: m.hidden === true,
    public: m.public === true,
    thumb: { light: has(`thumbnails/${slug}-light.png`), dark: has(`thumbnails/${slug}-dark.png`) },
    og: { image: has(`og/${slug}.png`), video: has(`og/${slug}.mp4`) },
  };
};

const entries = [];
const slugs = [];
for (const dir of readdirSync(join(root, "prototypes"), { withFileTypes: true })) {
  if (!dir.isDirectory()) continue;
  const slug = dir.name;
  const where = `prototypes/${slug}`;
  if (!SLUG.test(slug)) fail(`${where}: folder names are lowercase letters, digits and dashes`);
  for (const file of ["page.tsx", "metadata.json", "HOW_IT_WORKS.md"]) {
    if (!existsSync(join(root, where, file))) fail(`${where} is missing ${file}`);
  }
  entries.push({ kind: "prototype", href: `/p/${slug}`, ...common(slug, readJson(join(root, where, "metadata.json")), where) });
  slugs.push(slug);
}

for (const file of readdirSync(join(root, "sites"))) {
  if (!file.endsWith(".json")) continue;
  const slug = file.slice(0, -5);
  const where = `sites/${file}`;
  if (!SLUG.test(slug)) fail(`${where}: file names are lowercase letters, digits and dashes`);
  if (slugs.includes(slug)) fail(`${where} has the same name as a prototype`);
  const m = readJson(join(root, where));
  const host = m.host ?? `${slug}.emmett.wtf`;
  entries.push({ kind: "site", href: `https://${host}`, host, ...common(slug, m, where) });
}

entries.sort((a, b) => b.updatedAt.localeCompare(a.updatedAt));

const out = join(root, "lib/generated");
mkdirSync(out, { recursive: true });
writeFileSync(join(out, "manifest.json"), JSON.stringify(entries, null, 2) + "\n");
writeFileSync(
  join(out, "registry.ts"),
  `// Generated by scripts/manifest.mjs.
import type { ComponentType } from "react";

export const registry: Record<string, () => Promise<{ default: ComponentType }>> = {
${slugs.map((s) => `  ${JSON.stringify(s)}: () => import("@/prototypes/${s}/page"),`).join("\n")}
};
`,
);
console.log(`manifest: ${slugs.length} prototypes, ${entries.length - slugs.length} sites`);
